// ------------------------------------------------------------------
// MAIN COMPONENT
// ------------------------------------------------------------------
const AppSwitcher: React.FC<AppSwitcherProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 8,
  waContactName = "Loretta Fleming",
  dcContactName = "Nina Riley",
  phoneWallpaper = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout metrics
  const phoneWidth = 380;
  const phoneHeight = 800;
  const cardGap = 30;
  const totalSwipeDistance = phoneWidth + cardGap;

  // Animation Timings (in frames based on fps)
  const tStartMultiTask = Math.floor(1.5 * fps); // 1.5s
  const tStartSwipe = Math.floor(3.0 * fps);     // 3.0s
  const tStartZoom = Math.floor(4.5 * fps);      // 4.5s

  // Spring animations for phases
  const multiTaskSpr = spring({
    frame: Math.max(0, frame - tStartMultiTask),
    fps,
    config: { damping: 16, stiffness: 100 },
  });

  const swipeSpr = spring({
    frame: Math.max(0, frame - tStartSwipe),
    fps,
    config: { damping: 18, stiffness: 90 },
  });

  const zoomSpr = spring({
    frame: Math.max(0, frame - tStartZoom),
    fps,
    config: { damping: 16, stiffness: 100 },
  });

  // Derived values
  // Scale down to 0.75, then back to 1. 
  // zoomSpr naturally overtakes multiTaskSpr visually, but to be clean:
  const isZooming = frame > tStartZoom;
  const currentScale = isZooming
    ? interpolate(zoomSpr, [0, 1], [0.75, 1])
    : interpolate(multiTaskSpr, [0, 1], [1, 0.75]);

  // Translate entire inner container to swipe
  const containerTranslateX = interpolate(swipeSpr, [0, 1], [0, -totalSwipeDistance]);

  // Card styling that changes when scaled
  const cardBorderRadius = interpolate(currentScale, [0.75, 1], [32, 0]);
  const cardBoxShadow = interpolate(currentScale, [0.75, 1], [0.4, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, alignItems: "center", justifyContent: "center" }}>
      
      {/* Outer Phone Device Frame */}
      <div
        style={{
          width: phoneWidth + 24, // 12px bezel each side
          height: phoneHeight + 24,
          backgroundColor: "#1C1C1E",
          borderRadius: 48,
          position: "relative",
          boxShadow: "0 25px 60px rgba(0,0,0,0.5), inset 0 0 0 2px #333, inset 0 0 0 6px black",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        {/* Phone Screen Area (Clips the content) */}
        <div
          style={{
            width: phoneWidth,
            height: phoneHeight,
            backgroundColor: "#000",
            borderRadius: 36,
            overflow: "hidden",
            position: "relative",
            transition: "none",
          }}
        >
          {/* Phone Background Wallpaper */}
          <Img
            src={phoneWallpaper}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              zIndex: 0,
            }}
          />

          {/* App Switcher Container (Translates X) */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: "100%",
              height: "100%",
              transform: `translateX(${containerTranslateX}px)`,
              display: "flex",
              alignItems: "center",
              gap: cardGap,
              transition: "none",
              zIndex: 1,
            }}
          >
            {/* App 1: WhatsApp */}
            <div
              style={{
                width: phoneWidth,
                height: phoneHeight,
                flexShrink: 0,
                transform: `scale(${currentScale})`,
                transformOrigin: "center center",
                borderRadius: cardBorderRadius,
                overflow: "hidden",
                boxShadow: `0 10px 40px rgba(0,0,0,${cardBoxShadow})`,
                transition: "none",
              }}
            >
              <WhatsAppUI contactName={waContactName} />
            </div>

            {/* App 2: Discord */}
            <div
              style={{
                width: phoneWidth,
                height: phoneHeight,
                flexShrink: 0,
                transform: `scale(${currentScale})`,
                transformOrigin: "center center",
                borderRadius: cardBorderRadius,
                overflow: "hidden",
                boxShadow: `0 10px 40px rgba(0,0,0,${cardBoxShadow})`,
                transition: "none",
              }}
            >
              <DiscordUI contactName={dcContactName} />
            </div>
          </div>

          {/* Fixed Status and Nav Bars overlayed on the device screen */}
          <FixedStatusBar />
          <FixedNavBar />
          
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AppSwitcher;